import { SITES, resolveSite, type Site } from './model';

// Translate only labels that were generated by older versions. Keep names
// entered by the user exactly as they were saved.
const LEGACY_PRESET_NAMES: Record<string, string> = {
  shackleton: 'Шеклтон', mouton: 'Моутон', malapert: 'Малаперт', cabeus: 'Кабеус',
};

function currentCustomName(name: string): string {
  if (name === 'Власна точка') return 'Custom point';
  if (name === 'Поруч на тому самому валу') return 'Nearby point on the same ridge';
  return name;
}

export interface Passport {
  site: Site;
  date: string;
  dayOffset: number;
  markerX: number;
}

/** Preserve the exact teaching-model site and the visual marker position. */
export function capturePassport(site: Site, date: string, dayOffset: number, markerX: number): Passport {
  return { site: { ...site }, date, dayOffset, markerX };
}

export function appendPassport(passports: readonly Passport[], passport: Passport): Passport[] {
  return [...passports, passport].slice(-3);
}

export function cyclePassportIndex(activeIndex: number | null, count: number, direction: -1 | 1): number | null {
  if (count < 2) return null;
  const current = activeIndex ?? (direction === 1 ? -1 : 0);
  return (current + direction + count) % count;
}

export function matchesPassport(
  passport: Passport, site: Site, date: string, dayOffset: number, markerX: number,
): boolean {
  return passport.site.id === site.id && passport.site.name === site.name &&
    passport.site.lat === site.lat &&
    passport.site.lon === site.lon && passport.date === date &&
    passport.dayOffset === dayOffset && Math.abs(passport.markerX - markerX) <= 1e-6;
}

function isSiteSnapshot(value: unknown): value is Site {
  if (!value || typeof value !== 'object') return false;
  const site = value as Partial<Site>;
  return typeof site.id === 'string' && typeof site.name === 'string' &&
    typeof site.teachingPreset === 'boolean' &&
    [site.lat, site.lon, site.iceKm, site.sunMask, site.sitePhase, site.siteSunBias, site.siteEarthBase]
      .every(number => typeof number === 'number' && Number.isFinite(number)) &&
    site.lat! >= -90 && site.lat! <= -80 && site.lon! >= -180 && site.lon! <= 180;
}

function parsePassport(value: unknown): Passport | null {
  if (!value || typeof value !== 'object') return null;
  const item = value as Record<string, unknown>;
  if (typeof item.date !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(item.date) ||
      !Number.isFinite(Date.parse(`${item.date}T00:00:00Z`)) ||
      typeof item.dayOffset !== 'number' || !Number.isFinite(item.dayOffset) ||
      item.dayOffset < 0 || item.dayOffset > 29.5) return null;
  let site: Site | null = null;
  if (isSiteSnapshot(item.site)) {
    // A passport records the chosen point, not the derived astronomy and ridge
    // values from the app version that saved it. Recalculate those on load.
    site = resolveSite(item.site.lat, item.site.lon,
      item.site.teachingPreset ? item.site.name : currentCustomName(item.site.name),
      item.site.teachingPreset);
  }
  else if (typeof item.lat === 'number' && typeof item.lon === 'number' && typeof item.name === 'string') {
    // v2 passports held coordinates but not the full site or marker position.
    // Avoid snapping a legacy custom coordinate onto a nearby preset.
    const preset = SITES.find(candidate =>
      Math.abs(candidate.lat - (item.lat as number)) < .0001 &&
      Math.abs(candidate.lon - (item.lon as number)) < .0001 &&
      (candidate.name === item.name || LEGACY_PRESET_NAMES[candidate.id] === item.name));
    site = resolveSite(item.lat, item.lon, preset?.name ?? currentCustomName(item.name), Boolean(preset));
  }
  if (!site) return null;
  const markerX = typeof item.markerX === 'number' && Number.isFinite(item.markerX) &&
    item.markerX >= .15 && item.markerX <= .85 ? item.markerX : .5;
  return { site, date: item.date, dayOffset: item.dayOffset, markerX };
}

/** Read both current snapshots and passports saved by the previous version. */
export function decodePassports(raw: unknown): Passport[] {
  if (!Array.isArray(raw)) return [];
  return raw.map(parsePassport).filter((item): item is Passport => item !== null).slice(-3);
}
